def evaluate(x):
    """x: (N, in_dim) normalized -> (N, 2) normalized (psi, Jpsi)."""
    x = np.asarray(x, dtype=np.float64)
    h0 = np.zeros((x.shape[0], 10))
    for o, i, e in _LAYER0:
        h0[:, o] += e(x[:, i])
    h1 = np.zeros((x.shape[0], 2))
    for o, i, e in _LAYER1:
        h1[:, o] += e(h0[:, i])
    return h1
